/**
 * @suppress
 */
public object FfiConverterTypeGreekCore: FfiConverter<GreekCore, Pointer> {

    override fun lower(value: GreekCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): GreekCore {
        return GreekCore(value)
    }

    override fun read(buf: ByteBuffer): GreekCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: GreekCore) = 8UL

    override fun write(value: GreekCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



